/*
 * prog24_query_string_parser
 *
 * The original binary reads a line from standard input, treats it as a URL‑encoded
 * query string (key=value pairs separated by '&'), URL‑decodes each key and value,
 * and prints each pair on its own line as:
 *
 *     key=value
 *
 * If no input is available (EOF on stdin) the program prints the literal string
 * "NO_INPUT" (followed by a newline) and exits.
 *
 * The implementation below follows the same observable behaviour without
 * reproducing the obfuscated state‑machine used in the original binary.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048   /* size used by the original binary (0x800) */

/* ---------------------------------------------------------------------------
 * URL‑decode a fragment.
 *
 *  src   – pointer to the encoded data
 *  len   – number of bytes to decode
 *  dest  – buffer where the decoded string is written (must be large enough)
 *
 * The decoder implements the behaviour observed in the original `decode`
 * function:
 *   * '+' is translated to a space character.
 *   * "%XY" where X and Y are hexadecimal digits is translated to the byte
 *     value represented by those digits.
 *   * All other characters are copied unchanged.
 * The result is NUL‑terminated.
 * --------------------------------------------------------------------------- */
static void url_decode(const char *src, size_t len, char *dest)
{
    size_t i = 0, j = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dest[j++] = ' ';
            ++i;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            /* Convert two hex digits to a byte */
            char hi = src[i + 1];
            char lo = src[i + 2];
            int hi_val = (hi >= '0' && hi <= '9') ? hi - '0' :
                         (hi >= 'a' && hi <= 'f') ? hi - 'a' + 10 :
                         hi - 'A' + 10;
            int lo_val = (lo >= '0' && lo <= '9') ? lo - '0' :
                         (lo >= 'a' && lo <= 'f') ? lo - 'a' + 10 :
                         lo - 'A' + 10;
            dest[j++] = (char)((hi_val << 4) | lo_val);
            i += 3;
        } else {
            dest[j++] = c;
            ++i;
        }
    }
    dest[j] = '\0';
}

/* ---------------------------------------------------------------------------
 * Main program – reads a line, parses it as a query string and prints the
 * decoded key/value pairs.
 * --------------------------------------------------------------------------- */
int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_LINE];
    static char val[MAX_LINE];

    /* Read a line from stdin.  The original binary used fgets with a size of
       0x800 (2048) bytes. */
    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing CR and LF characters (the original code handled both). */
    size_t linelen = strlen(line);
    while (linelen > 0 &&
          (line[linelen - 1] == '\n' || line[linelen - 1] == '\r')) {
        line[--linelen] = '\0';
    }

    /* If the line is now empty, nothing is printed – this matches the
       original behaviour. */
    if (linelen == 0) {
        return 0;
    }

    /* Parse the line as a series of key=value pairs separated by '&'. */
    const char *p = line;
    while (*p) {
        /* Locate the end of the current token (either '&' or end of string). */
        const char *token_end = strchr(p, '&');
        if (!token_end) {
            token_end = p + strlen(p);
        }

        /* Within the token, locate the first '=' (if any). */
        const char *eq = memchr(p, '=', (size_t)(token_end - p));

        if (eq) {
            /* Key is the substring before '=', value is after '=' up to token_end. */
            size_t key_len = (size_t)(eq - p);
            size_t val_len = (size_t)(token_end - (eq + 1));

            url_decode(p, key_len, key);
            url_decode(eq + 1, val_len, val);
        } else {
            /* No '=', the whole token is the key and the value is empty. */
            url_decode(p, (size_t)(token_end - p), key);
            val[0] = '\0';
        }

        printf("%s=%s\n", key, val);

        /* Advance to the next token (skip the '&' if present). */
        p = (*token_end == '&') ? token_end + 1 : token_end;
    }

    return 0;
}
